private final Semaphore trackingSlots = new Semaphore(64);

StatusReply report(StatusLine line) throws InterruptedException {
    trackingSlots.acquire();
    try {
        return tracking.send(line);        // 135 ms
    } finally {
        trackingSlots.release();
    }
}

